-- 1. Beneficios nuevos verificados el 2026-11-04
insert into public.beneficios (tipo, nombre, oferta, detalle, como, requisito, categoria, zona, link, fuente, verificado_en, orden, activo, es_ejemplo, etiqueta, destacado, gratis, para_todos)
select 'digital', 'Ruta de Emprendimiento Campus Nova', 'Programas para llevar tu idea a prototipo, MVP y mercado', 'La incubadora de la Javeriana Cali tiene tres programas: Origen (de la idea al prototipo, 3 meses, virtual), Evolución (del prototipo al MVP, 4 meses) y Expansión (del MVP al mercado, 3 meses).', array['Entra a la página de Incubación de Campus Nova', 'Haz el diagnóstico para saber en qué etapa está tu emprendimiento', 'Inscríbete en el programa que te corresponda cuando abra la cohorte']::text[], 'Origen está abierto a cualquier persona. Evolución y Expansión son solo para la comunidad Javeriana, y Expansión pide al menos un año de operación. La página no dice si tiene costo.', 'Apoyo para emprender', '', 'https://www.javerianacali.edu.co/centro-de-innovacion-y-emprendimiento/Incubacion', 'https://www.javerianacali.edu.co/centro-de-innovacion-y-emprendimiento/Incubacion', date '2026-11-04', 5, true, false, 'JAVERIANA', true, false, false
where not exists (select 1 from public.beneficios where nombre = 'Ruta de Emprendimiento Campus Nova');
insert into public.beneficios (tipo, nombre, oferta, detalle, como, requisito, categoria, zona, link, fuente, verificado_en, orden, activo, es_ejemplo, etiqueta, destacado, gratis, para_todos)
select 'digital', 'Asesoría EmprendeLab', 'Asesoría de 30 a 40 minutos para tu emprendimiento', 'Una sesión con el equipo de Campus Nova, virtual o presencial, para resolver dudas como qué paso sigue con tu idea o cómo crecer si ya vendes.', array['Entra a la página de Incubación de Campus Nova', 'Toca Agenda tu asesoría y elige un horario', 'Lleva una descripción corta de tu emprendimiento y tu duda principal']::text[], 'Abierta a la comunidad Javeriana y a externos. La página no dice si tiene costo.', 'Apoyo para emprender', '', 'https://www.javerianacali.edu.co/centro-de-innovacion-y-emprendimiento/Incubacion', 'https://www.javerianacali.edu.co/centro-de-innovacion-y-emprendimiento/Incubacion', date '2026-11-04', 6, true, false, 'ASESORÍA', true, false, false
where not exists (select 1 from public.beneficios where nombre = 'Asesoría EmprendeLab');
insert into public.beneficios (tipo, nombre, oferta, detalle, como, requisito, categoria, zona, link, fuente, verificado_en, orden, activo, es_ejemplo, etiqueta, destacado, gratis, para_todos)
select 'digital', 'Matrícula mercantil sin costo', 'No pagas la matrícula ni la primera renovación', 'Por la Ley 1780 de 2016, las pequeñas empresas de jóvenes de 18 a 35 años quedan exentas del pago de la matrícula mercantil y de la renovación del año siguiente.', array['Revisa en la página de la Cámara de Comercio de Cali si cumples los requisitos', 'Pide el beneficio de la Ley 1780 al hacer la matrícula y lleva tu documento de identidad', 'Renueva en los tres primeros meses del año siguiente para no perderlo']::text[], 'Tener entre 18 y 35 años, hasta 50 trabajadores y activos de hasta 5.000 salarios mínimos. Si es sociedad, los jóvenes deben tener más de la mitad del capital. No es solo para estudiantes.', 'Apoyo para emprender', '', 'https://www.ccc.org.co/sedevirtual/tramites-de-registros-publicos/registro-mercantil/tramites/matricula/', 'https://www.ccc.org.co/sedevirtual/tramites-de-registros-publicos/registro-mercantil/tramites/matricula/', date '2026-11-04', 7, true, false, 'MATRÍCULA $0', true, true, true
where not exists (select 1 from public.beneficios where nombre = 'Matrícula mercantil sin costo');
insert into public.beneficios (tipo, nombre, oferta, detalle, como, requisito, categoria, zona, link, fuente, verificado_en, orden, activo, es_ejemplo, etiqueta, destacado, gratis, para_todos)
select 'digital', 'Google AI Plus para estudiantes', '1 año gratis de Google AI Plus', 'Gemini con límites de uso 2 veces más altos, Gemini Omni y 400 GB de almacenamiento en la nube. Después del año cuesta COP 19.900 al mes si no cancelas.', array['Entra a la página de Gemini para estudiantes en Colombia', 'Toca Obtén el plan gratuito para estudiantes y verifica que estudias', 'Agrega una forma de pago y cancela antes del año si no quieres pagar después']::text[], 'Estudiante universitario mayor de 18 años. Puedes reclamarlo hasta el 31 de diciembre de 2026. Se verifica cada año.', 'Productividad', '', 'https://gemini.google/co/students/?hl=es-419', 'https://gemini.google/co/students/?hl=es-419', date '2026-11-04', 8, true, false, '1 AÑO GRATIS', true, true, false
where not exists (select 1 from public.beneficios where nombre = 'Google AI Plus para estudiantes');
insert into public.beneficios (tipo, nombre, oferta, detalle, como, requisito, categoria, zona, link, fuente, verificado_en, orden, activo, es_ejemplo, etiqueta, destacado, gratis, para_todos)
select 'digital', 'Software de la universidad en la nube', 'Programas licenciados desde cualquier dispositivo', 'Con las aplicaciones virtuales de la Javeriana Cali usas gratis el software básico y de procesamiento gráfico avanzado que compró la universidad, dentro o fuera del campus.', array['Entra a Herramientas digitales en la página de estudiantes', 'Abre Aplicaciones virtuales con tu usuario Javeriana', 'Si aún no tienes el servicio, pídelo a requerimientos@javerianacali.edu.co']::text[], 'Ser estudiante de la Javeriana Cali. Es para uso académico.', 'Diseño', '', 'https://www.javerianacali.edu.co/estudiantes/recursos-virtuales/herramientas-digitales', 'https://www.javerianacali.edu.co/estudiantes/recursos-virtuales/herramientas-digitales', date '2026-11-04', 25, true, false, 'GRATIS', true, true, false
where not exists (select 1 from public.beneficios where nombre = 'Software de la universidad en la nube');
insert into public.beneficios (tipo, nombre, oferta, detalle, como, requisito, categoria, zona, link, fuente, verificado_en, orden, activo, es_ejemplo, etiqueta, destacado, gratis, para_todos)
select 'digital', 'Perfil de Negocio de Google', 'Aparece gratis en Google Maps y en la Búsqueda', 'Tus clientes ven tu negocio, tus datos de contacto y tus reseñas cuando te buscan en Google. Crear y administrar el perfil no tiene costo.', array['Entra a business.google.com/add con tu cuenta de Google', 'Toca Agrega tu empresa a Google y completa los datos', 'Elige un método de verificación y sigue los pasos']::text[], 'Cumplir los lineamientos de Google para negocios. Gratis para todos.', 'Vender', '', 'https://business.google.com/es-all/business-profile/', 'https://support.google.com/business/answer/2911778?hl=es-419', date '2026-11-04', 190, true, false, 'GRATIS', true, true, true
where not exists (select 1 from public.beneficios where nombre = 'Perfil de Negocio de Google');
