select 'digital', 'Fondo Emprender del SENA', 'Capital semilla para crear o fortalecer tu negocio', 'El SENA abre convocatorias durante el año con recursos para emprendimientos. Cada una define región, sector, población y monto.', array['Entra a la página de convocatorias vigentes de Fondo Emprender', 'Busca una que aplique para Cali o para tu perfil', 'Lee los términos de referencia antes de postularte']::text[], 'Depende de cada convocatoria. En noviembre de 2026 la única abierta para el Valle (la 168) es para negocios ya constituidos afectados por el sismo del 10 de agosto.', 'Apoyo para emprender', '', 'https://www.fondoemprender.com/SitePages/FondoEmprenderConvocatoriasVigentes.aspx', 'https://www.fondoemprender.com/SitePages/FondoEmprenderConvocatoriasVigentes.aspx', date '2026-11-04', 9, true, false, 'CAPITAL', false, true, true
where not exists (select 1 from public.beneficios where nombre = 'Fondo Emprender del SENA');
