select 'digital', 'Cursos de la Cámara de Comercio de Cali', 'Cursos virtuales sin costo para tu negocio', 'En su Campus Virtual hay cursos como Marketing potenciado con IA, Gestión del dinero en Excel y Transformación digital para empresas. La programación cambia cada mes.', array['Entra al calendario de capacitaciones de la Cámara de Comercio de Cali', 'Busca los que dicen Sin costo', 'Abre el curso que te interese y sigue los pasos para inscribirte']::text[], 'Revisa las condiciones de cada curso. No es solo para estudiantes.', 'Aprender', '', 'https://www.ccc.org.co/capacitaciones-eventos-y-convocatorias/maraton-de-asesorias/', 'https://www.ccc.org.co/capacitaciones-eventos-y-convocatorias/maraton-de-asesorias/', date '2026-11-04', 205, true, false, 'SIN COSTO', false, true, true
where not exists (select 1 from public.beneficios where nombre = 'Cursos de la Cámara de Comercio de Cali');
