select 'digital', 'Bases de datos de la Biblioteca', 'Libros, revistas y videos digitales desde tu casa', 'Sirven para investigar tu mercado, tu sector o tu competencia antes de lanzar. Funcionan dentro y fuera del campus.', array['Entra a Recursos digitales de la Biblioteca', 'Filtra por tu facultad o por tipo de recurso', 'Si algo no carga, escribe a requerimientos@javerianacali.edu.co']::text[], 'Ser estudiante de la Javeriana Cali.', 'Aprender', '', 'https://www.javerianacali.edu.co/biblioteca/recursos-digitales', 'https://www.javerianacali.edu.co/biblioteca/recursos-digitales', date '2026-11-04', 200, true, false, 'INCLUIDO', false, true, false
