select 'digital', 'HubSpot Academy', 'Curso de marketing digital con certificado gratis', 'Curso en español y a tu ritmo. Aprendes a crear contenido para blog, video y email y a usar las herramientas gratuitas de HubSpot.', array['Entra al curso de marketing digital de HubSpot Academy', 'Crea tu cuenta gratis', 'Completa las lecciones y el examen para recibir el certificado']::text[], 'Gratis para todos.', 'Aprender', '', 'https://academy.hubspot.com/es/courses/digital-marketing', 'https://academy.hubspot.com/es/courses/digital-marketing', date '2026-11-04', 210, true, false, 'GRATIS', false, true, true
