-- 2. Ajustes a los beneficios actuales
-- Miro: su foro oficial dice que no reciben solicitudes nuevas del plan Education
update public.beneficios set activo = false, verificado_en = date '2026-11-04' where nombre = 'Miro' and tipo = 'digital';
-- Etiquetas de más de 14 caracteres
update public.beneficios set etiqueta = 'ESTUDIANTE', verificado_en = date '2026-11-04' where nombre in ('YouTube Premium Estudiantes', 'Samsung Estudiantes') and etiqueta = 'PRECIO ESTUDIANTE';
-- Dominio: el Student Pack no trae .tech
update public.beneficios set detalle = 'Viene en el paquete de GitHub para estudiantes, con Namecheap. El paquete también trae un dominio gratis de Name.com en algunas extensiones y un certificado SSL por un año.' where nombre = 'Dominio web gratis';
-- GitHub: el plan de Copilot para estudiantes se llama Copilot Student
update public.beneficios set detalle = replace(detalle, 'GitHub Copilot para estudiantes', 'GitHub Copilot Student') where nombre = 'GitHub Student Pack';
-- Affinity: fuente oficial en lugar de un blog
update public.beneficios set fuente = 'https://www.affinity.studio/es_419' where nombre = 'Affinity';
-- Requisitos que confirma la fuente
update public.beneficios set requisito = 'Aplica con tu correo de la universidad y verificación de estudiante. Figma lo ofrece solo en algunas regiones: confirma en su página que aplique en Colombia.' where nombre = 'Figma';
update public.beneficios set requisito = 'Correo universitario como correo principal de la cuenta. Si pasas ese espacio a un plan pago, pierdes el plan Education.' where nombre = 'Notion';
update public.beneficios set como = array['Pregunta al CSI cómo activarla con tu usuario institucional', 'Escribe desde tu correo Javeriana a requerimientoscsi@javerianacali.edu.co']::text[] where nombre = 'Suite de Adobe';

commit;
